style.css:
@-moz-document domain("youtube.com") {
/* Couleur d'arrière-plan principale */
  body, #content, ytd-app {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
  }

  /* Barre de navigation */
  ytd-masthead, tp-yt-app-header {
    background-color: #1a1a1a !important;
    border-bottom: 1px solid #333 !important;
  }

  /* Miniatures et cartes */
  ytd-rich-grid-media, ytd-video-renderer, ytd-playlist-renderer {
    background-color: #181818 !important;
    border-radius: 10px !important;
    transition: transform 0.2s ease;
  }

  /* Effet de survol */
  ytd-rich-grid-media:hover, ytd-video-renderer:hover {
    transform: scale(1.02);
    background-color: #202020 !important;
  }

  /* Texte et titres */
  #video-title, yt-formatted-string, a {
    color: #e0e0e0 !important;
  }

  /* Supprimer les pubs visuelles (optionnel) */
  ytd-promoted-sparkles-web-renderer, ytd-ad-slot-renderer {
    display: none !important;
  }

  /* Boutons */
  button, yt-icon-button {
    color: #fff !important;
  }

  /* Commentaires */
  ytd-comment-renderer {
    background-color: #181818 !important;
    border-radius: 8px !important;
    padding: 8px !important;
    margin-bottom: 10px !important;
  }
}
